def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform separator row, which divides the grid into equal halves.
    sep = None
    for i, row in enumerate(grid):
        if i > 0 and h - i - 1 == i and len(set(row)) == 1:
            sep = i
            break
    if sep is None:
        sep = h // 2

    top = grid[:sep]
    bottom = grid[sep + 1:]
    out = [[3] * w for _ in range(sep)]

    for r in range(sep):
        for c in range(w):
            if top[r][c] != 9 or bottom[r][c] != 9:
                # In the demonstration, 9 is the background above and below.
                # For other palettes, the common color is the background.
                pass

    # Determine the background independently in each half.
    from collections import Counter
    top_bg = Counter(v for row in top for v in row).most_common(1)[0][0]
    bottom_bg = Counter(v for row in bottom for v in row).most_common(1)[0][0]
    for r in range(sep):
        for c in range(w):
            if top[r][c] != top_bg or bottom[r][c] != bottom_bg:
                out[r][c] = 9
    return out
