def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(i for i, row in enumerate(grid) if len(set(row)) == 1)
    n = min(sep, h - sep - 1)
    top = grid[:n]
    bottom = grid[sep + 1:sep + 1 + n]

    def background(panel):
        counts = {}
        for row in panel:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)

    top_bg = background(top)
    bottom_bg = background(bottom)
    return [
        [9 if top[r][c] != top_bg or bottom[r][c] != bottom_bg else 3
         for c in range(w)]
        for r in range(n)
    ]
